<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>My Joke Website</title>
    <style>
        body {
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            margin: 0;
            background-color: lightgray;
            font-family: Arial, sans-serif;
        }
        .joke-box {
            background-color: white;
            border: 3px solid blue;
            padding: 20px;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
        }
        button {
            background-color: green;
            color: white;
            text-align: center;
            cursor: pointer;
            border-radius: 5px;
            padding: 10px 20px;
            transition: all 0.3s ease-in-out;
        }
        button:hover {
            box-shadow: inset 0px 0px 0px #3300ff;
            border-color: #333;
        }
    </style>
</head>
<body>
    <div class="joke-box">
        <h1>My Joke Website</h1>
        <div id="jokeContainer">
            <p>Loading...</p>
        </div>
        <button onclick="showPunchline()">Push to Reveal Punchline</button>
    </div>

    <script>
        window.onload = function () {
            var jokeText = "Why don't scientists trust atoms? Because they make up everything.";
            document.getElementById("jokeContainer").innerHTML = jokeText;
        };

        function showPunchline() {
            // Logic to call a rest API or use local data for jokes
            var punchline = "Because they make up everything!";
            document.getElementById("jokeContainer").innerHTML += "<br><span style='color: blue;'>" + punchline + "</span>";
        }
    </script>
</body>
</html>
